EMR Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("emr_service", "EMR Service") {
    Component("EMR_API_Controller", "EMR API Controller", "Go / Node.js", "Exposes REST and gRPC endpoints for electronic medical records management.")
    Component("Clinical_Workflow_Manager", "Clinical Workflow Manager", "Go / Node.js", "Manages clinical workflows, chart notes, and high-performance data processing.")
    Component("EMR_Data_Access_Layer", "EMR Data Access Layer", "Go / Node.js, PostgreSQL protocol", "Handles secure database transactions and AES-256 encrypted queries with the Data Store.")
}

Rel("EMR_API_Controller", "Clinical_Workflow_Manager", "Delegates clinical requests")
Rel("Clinical_Workflow_Manager", "EMR_Data_Access_Layer", "Persists and retrieves medical records")
@enduml

Data Store.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Data Store container

Container_Boundary(data_store, "Data Store") {
    Component(Primary_Relational_Database, "Primary Relational Database", "PostgreSQL 16 & Read-Replicas", "Provides core transactional data storage and offloads analytical queries with active-passive replication.")
    Component(Audit_Archive_Object_Store, "Audit & Archive Object Store", "S3-compatible Object Storage with Object Lock", "Enforces immutable 10-year WORM retention and automated tiering.")
    Component(Read_Replica_Cluster, "Read Replica Cluster", "PostgreSQL Read-Replicas", "Handles read-heavy workloads and offloads analytical queries from the primary transactional database.")
}

Rel(Primary_Relational_Database, Audit_Archive_Object_Store, "S3 API / TLS 1.3", "")
Rel(Primary_Relational_Database, Read_Replica_Cluster, "Active-passive replication", "")

@enduml
